@RestController
@RequestMapping("/api/v1/orders")
public class SampleController {
  private final OrderService orderService;

  @PostMapping
  public ResponseEntity<OrderReceipt> createOrder(@RequestHeader("x-token") String token) {
    OrderReceipt receipt = orderService.acceptOrder(token);
    return ResponseEntity.accepted().body(receipt);
  }
}
